from bcc import BPF, USDT, SymbolCache
import ctypes as ct
import time
import sys
import os

# BPF program for counting strlen return values
bpf_text_count = """
BPF_HISTOGRAM(ret_hist);

int count_strlen_ret(struct pt_regs *ctx) {
    int ret = PT_REGS_RC(ctx);
    ret_hist.increment(bpf_log2l(ret));
    return 0;
}
"""

# BPF program for submitting resolver and implementation addresses
bpf_text_submit = """
BPF_PERF_OUTPUT(events);

struct data_t {
    u64 resolver_addr;
    u64 impl_addr;
};
int submit_addrs(struct pt_regs *ctx) {
    struct data_t data = {};
    data.resolver_addr = (u64)RESOLVER_ADDR;
    data.impl_addr = (u64)IMPL_ADDR;
    events.perf_submit(ctx, &data, sizeof(data));
    return 0;
}
"""

# Helper to get symbol of indirect function
def get_strlen_symbol(libc_path):
    symcache = SymbolCache([libc_path])
    for sym in symcache.get_symbols(libc_path):
        if sym.name == "strlen":
            return sym
    return None

# Helper to set addresses of resolver and implementation functions
def set_addrs(bpf, resolver_addr, impl_addr):
    bpf["RESOLVER_ADDR"] = ct.c_ulonglong(resolver_addr)
    bpf["IMPL_ADDR"] = ct.c_ulonglong(impl_addr)

# Helper to find offset of implementation function
def find_impl_offset(libc_path, impl_name):
    symcache = SymbolCache([libc_path])
    for sym in symcache.get_symbols(libc_path):
        if sym.name == impl_name:
            return sym.addr
    return None

def main():
    libc_path = None
    for path in ["/lib/x86_64-linux-gnu/libc.so.6", "/lib64/libc.so.6", "/usr/lib/libc.so.6"]:
        if os.path.exists(path):
            libc_path = path
            break
    if not libc_path:
        print("libc.so.6 not found")
        sys.exit(1)

    strlen_sym = get_strlen_symbol(libc_path)
    if not strlen_sym:
        print("strlen symbol not found")
        sys.exit(1)

    # Try to find the resolver and implementation function names
    resolver_name = None
    impl_name = None
    with open(libc_path, "rb") as f:
        data = f.read()
        if b"__strlen_avx2" in data:
            impl_name = "__strlen_avx2"
        elif b"__strlen_sse2" in data:
            impl_name = "__strlen_sse2"
        else:
            impl_name = "strlen"

        if b"__strlen_ifunc" in data:
            resolver_name = "__strlen_ifunc"
        elif b"__strlen_resolver" in data:
            resolver_name = "__strlen_resolver"
        else:
            resolver_name = None

    # Find implementation function offset
    impl_offset = find_impl_offset(libc_path, impl_name)
    if impl_offset is None:
        print("Implementation function not found")
        sys.exit(1)

    # Attach BPF program to implementation function
    bpf = BPF(text=bpf_text_count)
    bpf.attach_uprobe(name=libc_path, sym=impl_name, fn_name="count_strlen_ret", pid=-1, retprobe=True)

    print("Tracing strlen return values... Hit Ctrl-C to end.")

    try:
        while True:
            time.sleep(1)
            print("Histogram of strlen return values:")
            bpf["ret_hist"].print_log2_hist("strlen return")
            bpf["ret_hist"].clear()
    except KeyboardInterrupt:
        pass

if __name__ == "__main__":
    main()
